        providerID: String = "custom",
        languageModels: [String: any LanguageModel] = [:],
        decisionModels: [String: AIDecisionModelReference],
        fallbackProvider: (any AIProvider)? = nil
    ) -> AICustomProvider {
        return AICustomProvider(providerID: providerID, languageModels: languageModels, decisionModels: decisionModels, fallbackProvider: fallbackProvider)
    }
}
